package com.ryanjei.orushio.pve.map;import static org.junit.jupiter.api.Assertions.*;import com.ryanjei.orushio.pve.domain.MapProfileId;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;
class MapProfileTest{@Test void 必須不足では有効化できない(){MapProfile p=empty("a");assertFalse(p.setupComplete());assertThrows(IllegalArgumentException.class,()->p.withEnabled(true));}@Test void 必須項目が揃えば有効化できる(){assertTrue(complete("a").withEnabled(true).enabled());}static MapProfile empty(String id){return new MapProfile(new MapProfileId(id),id,false,"template",Map.of(),Map.of(),Instant.now());}static MapProfile complete(String id){BlockPoint p=new BlockPoint(0,64,0,0,0);Map<String,List<BlockPoint>> points=new HashMap<>();for(String k:MapProfile.REQUIRED_SINGLE_POINTS)points.put(k,List.of(p));points.put("normalCoreCandidates",List.of(p,p,p));points.put("shopPoints",List.of(p));Cuboid c=new Cuboid(0,0,0,1,1,1);Map<String,List<Cuboid>> areas=new HashMap<>();for(String k:MapProfile.REQUIRED_AREA_COUNTS.keySet())areas.put(k,List.of(c));return new MapProfile(new MapProfileId(id),id,false,"template",points,areas,Instant.now());}}
